<template><div class="page"><div class="toolbar"><el-input v-model="q.keyword" placeholder="规则名称或编码" clearable @keyup.enter.native="load"/><el-select v-model="q.type" clearable placeholder="规则类型"><el-option label="普通规则" value="NORMAL"/><el-option label="AI 规则" value="AI"/></el-select><el-button type="primary" @click="load">查询</el-button><el-button type="success" @click="edit()">新增规则</el-button></div><el-table :data="rows" v-loading="loading"><el-table-column prop="ruleCode" label="规则编码"/><el-table-column prop="ruleName" label="规则名称"/><el-table-column prop="ruleType" label="类型" width="100"/><el-table-column prop="targetType" label="对象" width="90"/><el-table-column prop="riskLevel" label="风险" width="90"/><el-table-column label="状态" width="90"><template slot-scope="s"><el-switch :value="s.row.enabled" @change="status(s.row,$event)"/></template></el-table-column><el-table-column label="操作" width="260"><template slot-scope="s"><el-button size="mini" @click="edit(s.row)">编辑</el-button><el-button size="mini" @click="copy(s.row)">复制</el-button><el-button size="mini" type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination class="pager" background layout="total,prev,pager,next" :total="total" :page-size="q.pageSize" @current-change="p=>{q.pageNum=p;load()}"/><el-dialog :title="form.id?'编辑扫描规则':'新增扫描规则'" :visible.sync="visible" width="680px"><el-form :model="form" label-width="110px"><el-form-item label="规则编码"><el-input v-model="form.ruleCode" placeholder="字母、数字、下划线或短横线"/></el-form-item><el-form-item label="规则名称"><el-input v-model="form.ruleName"/></el-form-item><el-form-item label="规则类型"><el-radio-group v-model="form.ruleType"><el-radio label="NORMAL">普通规则</el-radio><el-radio label="AI">AI 提示词</el-radio></el-radio-group></el-form-item><el-form-item label="扫描对象"><el-select v-model="form.targetType"><el-option label="全部" value="ALL"/><el-option label="代码" value="CODE"/><el-option label="文档" value="DOCUMENT"/></el-select></el-form-item><el-form-item label="风险等级"><el-select v-model="form.riskLevel"><el-option v-for="v in ['HIGH','MEDIUM','LOW','INFO']" :key="v" :value="v" :label="v"/></el-select></el-form-item><template v-if="form.ruleType==='NORMAL'"><el-form-item label="匹配方式"><el-radio-group v-model="form.matchType"><el-radio label="KEYWORD">关键字</el-radio><el-radio label="REGEX">正则</el-radio></el-radio-group></el-form-item><el-form-item label="匹配内容"><el-input type="textarea" :rows="3" v-model="form.matchContent"/></el-form-item><el-form-item label="文件类型"><el-input v-model="form.fileTypes" placeholder="java,js,md；仅使用英文逗号"/></el-form-item><el-form-item label="排除目录"><el-input v-model="form.excludePatterns" placeholder="target,node_modules；仅使用英文逗号"/></el-form-item></template><el-form-item v-else label="AI 提示词"><el-input type="textarea" :rows="5" v-model="form.promptContent"/></el-form-item><el-form-item label="问题说明"><el-input v-model="form.issueDescription"/></el-form-item><el-form-item label="整改建议"><el-input v-model="form.suggestion"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></span></el-dialog></div></template>
<script>import{ruleApi}from'../api';const empty=()=>({ruleCode:'',ruleName:'',ruleType:'NORMAL',targetType:'ALL',riskLevel:'MEDIUM',matchType:'KEYWORD',matchContent:'',caseSensitive:false,fileTypes:'',excludePatterns:'',issueDescription:'',suggestion:'',promptContent:'',enabled:true});const commaList=(v,pattern)=>{if(!v)return true;if(/[，；;]/.test(v)||v.startsWith(',')||v.endsWith(',')||v.includes(',,'))return false;return v.split(',').every(x=>x.trim()&&pattern.test(x.trim()))};export default{name:'RuleView',data:()=>({q:{keyword:'',type:'',pageNum:1,pageSize:20},rows:[],total:0,loading:false,visible:false,form:empty()}),created(){this.load()},methods:{async load(){this.loading=true;try{const r=await ruleApi.page(this.q);this.rows=r.list;this.total=r.total}finally{this.loading=false}},edit(r){this.form=r?Object.assign({},r):empty();this.visible=true},async save(){if(!this.form.ruleCode||!this.form.ruleName)return this.$message.warning('请填写规则编码和名称');if(!/^[A-Za-z0-9_-]+$/.test(this.form.ruleCode))return this.$message.warning('规则编码只能包含字母、数字、下划线和短横线');if(!commaList(this.form.fileTypes,/^[A-Za-z0-9]+(?:[._+-][A-Za-z0-9]+)*$/))return this.$message.warning('文件类型必须使用英文逗号分隔，且不能包含空项或非法字符');if(!commaList(this.form.excludePatterns,/^[^,，;；\s]+$/))return this.$message.warning('排除目录必须使用英文逗号分隔，且不能包含空项或空格');if(this.form.ruleType==='NORMAL'&&!this.form.matchContent)return this.$message.warning('请填写匹配内容');if(this.form.ruleType==='NORMAL'&&this.form.matchType==='REGEX'){try{new RegExp(this.form.matchContent)}catch(e){return this.$message.warning('正则表达式格式不正确')}}if(this.form.ruleType==='AI'&&!this.form.promptContent)return this.$message.warning('请填写 AI 提示词');this.form.id?await ruleApi.update(this.form.id,this.form):await ruleApi.create(this.form);this.visible=false;this.$message.success('保存成功');this.load()},async status(r,v){await ruleApi.status(r.id,v);r.enabled=v},async copy(r){await ruleApi.copy(r.id);this.$message.success('复制成功');this.load()},async remove(r){await this.$confirm('确认删除该规则？');await ruleApi.remove(r.id);this.load()}}}</script>
